    var items = g[1].map(function (id) { return byId(all, id); }).filter(Boolean); items.forEach(function (x) { used[x.id] = 1; });
    if (items.length) h += '<div class="exgrp"><div class="eyebrow">' + g[0] + '</div>' + items.map(exItemBtn).join('') + '</div>';
