  if (l.retenir) h += box('b-ret', 'À retenir', '<ul>' + l.retenir.map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>');
  if (l.erreur) h += box('b-err', 'Erreur fréquente', esc(l.erreur));
  if (l.methode) h += box('b-met', 'Méthode rapide', esc(l.methode));
